using ClosedXML.Excel;using ManpowerManagement.Data;using ManpowerManagement.Models;using Microsoft.AspNetCore.Mvc;using Microsoft.AspNetCore.Mvc.RazorPages;using Microsoft.EntityFrameworkCore;
namespace ManpowerManagement.Pages.Admin;
public class ImportModel(AppDbContext db):PageModel{[TempData]public string? Message{get;set;}public void OnGet(){}public async Task<IActionResult> OnPostEmployeesAsync(IFormFile file,DateOnly effectiveDate){if(file.Length==0)return BadRequest();using var s=file.OpenReadStream();using var wb=new XLWorkbook(s);var ws=wb.Worksheet(1);var headers=ws.Row(1).CellsUsed().ToDictionary(c=>c.GetString().Trim(),c=>c.Address.ColumnNumber,StringComparer.OrdinalIgnoreCase);var added=0;foreach(var row in ws.RowsUsed().Skip(1)){var id=row.Cell(headers["EmployeeId"]).GetString().Trim();if(string.IsNullOrWhiteSpace(id))continue;var workshop=await db.Workshops.FirstOrDefaultAsync(x=>x.Name==row.Cell(headers["Workshop"]).GetString().Trim());if(workshop==null)continue;var name=row.Cell(headers["FullName"]).GetString().Trim();var start=DateOnly.TryParse(row.Cell(headers["StartDate"]).GetString(),out var parsed)?parsed:effectiveDate;var type=Enum.TryParse<EmploymentType>(row.Cell(headers["EmploymentType"]).GetString().Replace(" ",""),true,out var parsedType)?parsedType:EmploymentType.NewComer;var e=await db.Employees.SingleOrDefaultAsync(x=>x.EmployeeId==id);if(e==null){e=new Employee{EmployeeId=id,FullName=name,StartDate=start,CurrentWorkshopId=workshop.Id,EmploymentType=type};db.Employees.Add(e);added++;}else{e.FullName=name;e.CurrentWorkshopId=workshop.Id;e.EmploymentType=type;}db.EmployeeHistories.Add(new EmployeeHistory{Employee=e,WorkshopId=workshop.Id,EmploymentType=type,EffectiveDate=effectiveDate,ChangedBy="Admin Import"});}await db.SaveChangesAsync();Message=$"Employee import completed ({added} new employees).";return RedirectToPage();}
public async Task<IActionResult> OnPostCalendarAsync(IFormFile file){if(file.Length==0)return BadRequest();using var s=file.OpenReadStream();using var wb=new XLWorkbook(s);var ws=wb.Worksheet(1);var h=ws.Row(1).CellsUsed().ToDictionary(c=>c.GetString().Trim(),c=>c.Address.ColumnNumber,StringComparer.OrdinalIgnoreCase);var count=0;foreach(var row in ws.RowsUsed().Skip(1)){if(!DateOnly.TryParse(row.Cell(h["WorkDate"]).GetString(),out var date))continue;var workshop=await db.Workshops.FirstOrDefaultAsync(x=>x.Name==row.Cell(h["Workshop"]).GetString().Trim());if(workshop==null)continue;var working=bool.TryParse(row.Cell(h["IsWorkingDay"]).GetString(),out var value)&&value;var c=await db.WorkCalendars.SingleOrDefaultAsync(x=>x.WorkshopId==workshop.Id&&x.WorkDate==date);if(c==null)db.WorkCalendars.Add(new WorkCalendar{WorkshopId=workshop.Id,WorkDate=date,IsWorkingDay=working});else c.IsWorkingDay=working;count++;}await db.SaveChangesAsync();Message=$"Calendar import completed ({count} rows).";return RedirectToPage();}}
